begin;
create table if not exists public.learning_events(id text primary key,user_id uuid not null references auth.users(id) on delete cascade,type text not null,payload jsonb not null default '{}',occurred_at timestamptz not null default now(),local_date date not null,version integer not null default 1,unique(user_id,id));
create table if not exists public.user_achievements(user_id uuid not null references auth.users(id) on delete cascade,achievement_id text not null,unlocked_at timestamptz not null default now(),source_event_id text not null,xp_awarded integer not null check(xp_awarded>=0),reward_payload jsonb not null default '{}',seen_at timestamptz,primary key(user_id,achievement_id));
create table if not exists public.user_achievement_stats(user_id uuid primary key references auth.users(id) on delete cascade,stats jsonb not null default '{}',timezone text not null default 'UTC',stabilizer_count integer not null default 0 check(stabilizer_count between 0 and 1),backfill_version integer not null default 0,updated_at timestamptz not null default now());
create table if not exists public.user_daily_activity(user_id uuid not null references auth.users(id) on delete cascade,local_date date not null,source text not null,qualifying boolean not null default true,stabilized boolean not null default false,primary key(user_id,local_date));
create table if not exists public.user_cosmetics(user_id uuid not null references auth.users(id) on delete cascade,kind text not null,reward_id text not null,active boolean not null default false,unlocked_at timestamptz not null default now(),primary key(user_id,kind,reward_id));
create index if not exists learning_events_user_date_idx on public.learning_events(user_id,local_date desc);
create index if not exists user_achievements_user_time_idx on public.user_achievements(user_id,unlocked_at desc);
alter table public.learning_events enable row level security;alter table public.user_achievements enable row level security;alter table public.user_achievement_stats enable row level security;alter table public.user_daily_activity enable row level security;alter table public.user_cosmetics enable row level security;
do $$ declare t text; op text; begin foreach t in array array['learning_events','user_achievements','user_achievement_stats','user_daily_activity','user_cosmetics'] loop foreach op in array array['select','insert','update','delete'] loop execute format('drop policy if exists %I on public.%I',t||'_own_'||op,t);if op='insert' then execute format('create policy %I on public.%I for insert to authenticated with check ((select auth.uid())=user_id)',t||'_own_'||op,t);elsif op='update' then execute format('create policy %I on public.%I for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id)',t||'_own_'||op,t);else execute format('create policy %I on public.%I for %s to authenticated using ((select auth.uid())=user_id)',t||'_own_'||op,t,op);end if;end loop;end loop;end $$;
grant select,insert,update,delete on public.learning_events,public.user_achievements,public.user_achievement_stats,public.user_daily_activity,public.user_cosmetics to authenticated;
commit;
